insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('anatomia-prompt', 'fundamentos', null, 1, true, 5, 'basico', 'Anatomia de um bom prompt', 'Anatomy of a good prompt', 'Os quatro blocos que transformam um pedido vago num resultado que podes usar: contexto, tarefa, restrições e formato.', 'The four building blocks that turn a vague request into something you can actually use: context, task, constraints and format.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Pedes à IA \"escreve um post sobre o meu restaurante\" e recebes um texto genérico, cheio de lugares-comuns, que podia ser de qualquer negócio. A IA não é fraca: só não sabe quem és, para quem escreves nem o que conta como um bom resultado. Tudo o que não dizes, ela inventa ou preenche com o mais banal.", "steps": [{"title": "Dá contexto", "text": "Diz quem és, qual é o teu negócio e para quem é o texto. Duas ou três frases chegam: \"Sou dono de uma pastelaria em Braga. Os clientes são famílias e trabalhadores da zona.\""}, {"title": "Define a tarefa e as restrições", "text": "Uma tarefa clara, com um verbo concreto (escreve, resume, compara, reescreve), e os limites: tamanho, tom, o que evitar. \"Escreve 3 legendas para Instagram, até 150 caracteres, tom próximo, sem emojis em excesso.\""}, {"title": "Diz como queres receber", "text": "Indica o formato final: lista numerada, um parágrafo, uma tabela, texto simples para colar. Se vais copiar para outra ferramenta, pede texto sem formatação."}], "before": {"prompt": "Escreve um post sobre a minha pastelaria.", "note": "Sem público, sem objetivo, sem formato. O resultado vai ser genérico e terás de o reescrever."}, "after": {"prompt": "Sou dono da Pastelaria Doce Braga, aberta desde 1998. Os clientes são famílias e quem trabalha na zona. Escreve 3 legendas para Instagram a anunciar o novo pastel de nata com framboesa, disponível a partir de sábado. Tom próximo e alegre, até 150 caracteres cada, no máximo 1 emoji. Termina cada uma com um convite para passar na loja. Entrega em lista numerada, em texto simples.", "note": "Contexto, tarefa, restrições e formato. A IA tem tudo o que precisa e o texto sai pronto a usar."}, "try": {"intro": "Preenche os campos e abre o prompt no Criar Prompt para o refinar passo a passo.", "target": "builder", "template": "Sou responsável por {{negocio}}. Os meus clientes são {{publico}}. Escreve {{tarefa}}. Tom {{tom}}. Evita jargão e frases feitas. Entrega o resultado em texto simples, pronto a colar.", "labels": {"tarefa": ["O que queres que a IA faça", "Ex.: 3 legendas para Instagram sobre o novo bolo"]}}, "checklist": ["Disse quem sou e qual é o negócio", "Disse para quem é o texto", "A tarefa tem um verbo concreto e uma quantidade", "Defini tamanho e tom", "Disse em que formato quero receber"], "tips": [{"title": "Regra dos 30 segundos", "text": "Se uma pessoa nova na tua equipa não conseguisse fazer a tarefa só com o teu pedido, a IA também não vai conseguir."}, {"title": "Guarda o que funciona", "text": "Quando um prompt dá bom resultado, guarda-o na Biblioteca. Da próxima vez mudas só os detalhes."}]}'::jsonb, '{"problem": "You ask the AI to \"write a post about my restaurant\" and get a bland, cliché-filled text that could belong to any business. The AI isn''t weak. It just doesn''t know who you are, who you''re writing for or what a good result looks like. Whatever you leave out, it fills with the most generic option.", "steps": [{"title": "Give context", "text": "Say who you are, what your business does and who the text is for. Two or three sentences are enough: \"I run a bakery in Bristol. Our customers are local families and office workers.\""}, {"title": "Set the task and the limits", "text": "One clear task with a concrete verb (write, summarise, compare, rewrite), plus the limits: length, tone, what to avoid. \"Write 3 Instagram captions, under 150 characters, warm tone, go easy on emojis.\""}, {"title": "Say how you want it delivered", "text": "Name the final format: numbered list, one paragraph, a table, plain text to paste. If you''ll paste it into another tool, ask for unformatted text."}], "before": {"prompt": "Write a post about my bakery.", "note": "No audience, no goal, no format. The result will be generic and you''ll end up rewriting it."}, "after": {"prompt": "I run Sunrise Bakery in Bristol, open since 1998. Our customers are local families and office workers. Write 3 Instagram captions announcing our new raspberry custard tart, available from Saturday. Warm, cheerful tone, under 150 characters each, at most 1 emoji. End each one by inviting people to drop by. Deliver as a numbered list in plain text.", "note": "Context, task, constraints and format. The AI has everything it needs and the copy is ready to use."}, "try": {"intro": "Fill in the fields and open the prompt in Create Prompt to refine it step by step.", "target": "builder", "template": "I run {{business}}. My customers are {{audience}}. Write {{task}}. Tone: {{tone}}. Avoid jargon and clichés. Deliver the result as plain text, ready to paste.", "labels": {"task": ["What you want the AI to do", "e.g. 3 Instagram captions about our new cake"]}}, "checklist": ["I said who I am and what the business is", "I said who the text is for", "The task has a concrete verb and a quantity", "I set the length and tone", "I said what format I want back"], "tips": [{"title": "The 30-second rule", "text": "If a new hire couldn''t do the task from your request alone, the AI can''t either."}, {"title": "Keep what works", "text": "When a prompt gives a great result, save it in your Library. Next time you only change the details."}]}'::jsonb from public.learn_lessons where slug = 'anatomia-prompt'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('contexto-negocio', 'fundamentos', null, 2, true, 5, 'basico', 'Dar contexto do teu negócio', 'Give the AI your business context', 'Uma ficha de negócio de 5 linhas que colas no início de qualquer prompt e que faz a IA escrever como tu.', 'A 5-line business profile you paste at the start of any prompt so the AI writes like you.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Cada vez que pedes um texto, a IA começa do zero. Não sabe o que vendes, quanto custa, quem são os teus clientes nem como falas com eles. Resultado: textos que soam a outra marca, promessas que não fazes e um tom que não é o teu.", "steps": [{"title": "Escreve a tua ficha de negócio", "text": "Cinco linhas: o que vendes, para quem, onde, o que te distingue e o preço médio. Exemplo: \"Clínica de fisioterapia em Aveiro. Clientes: desportistas amadores e pessoas com dores de costas. Diferença: avaliação de 60 minutos na primeira consulta. Preço: 45 euros por sessão.\""}, {"title": "Define o teu tom com exemplos", "text": "Em vez de \"tom profissional\", dá três palavras e uma frase tua real: \"Próximo, direto, sem exageros. Exemplo: Marca já a tua avaliação, nós tratamos do resto.\""}, {"title": "Diz o que nunca dizer", "text": "Lista o que está fora de questão: promessas de resultados, descontos que não fazes, palavras que detestas. A IA respeita limites quando os conhece."}], "before": {"prompt": "Escreve um email para os meus clientes sobre a promoção de novembro.", "note": "A IA vai inventar a promoção, o tom e talvez até o tipo de negócio."}, "after": {"prompt": "Contexto: clínica de fisioterapia em Aveiro. Clientes: desportistas amadores e pessoas com dores de costas. Tom: próximo, direto, sem exageros. Nunca prometer curas nem resultados garantidos. Tarefa: escreve um email curto (até 120 palavras) a anunciar 15% de desconto na avaliação inicial durante novembro. Assunto até 50 caracteres. Termina com um convite para marcar por telefone. Texto simples.", "note": "A ficha de negócio evita invenções e mantém o tom da marca em todos os textos."}, "try": {"intro": "Cria a tua ficha de negócio aqui e abre-a no Criar Prompt. Depois guarda-a na Biblioteca para reutilizar.", "target": "builder", "template": "Contexto do negócio: {{negocio}}, em {{localidade}}. Clientes: {{publico}}. O que nos distingue: {{oferta}}. Tom: {{tom}}. Nunca dizer: {{notas}}. Tarefa: {{tarefa}}. Entrega em texto simples.", "labels": {"notas": ["O que nunca dizer", "Ex.: prometer resultados"], "oferta": ["O que te distingue", "Ex.: entregas no próprio dia"], "tarefa": ["Tarefa", "Ex.: um email a anunciar a promoção de novembro"]}}, "checklist": ["A ficha diz o que vendo e para quem", "Incluí localidade e preço quando importa", "O tom tem palavras concretas e um exemplo meu", "Listei o que nunca dizer", "Guardei a ficha para reutilizar"], "tips": [{"title": "Uma ficha, muitos usos", "text": "A mesma ficha serve para posts, emails, respostas a avaliações e anúncios. Só muda a tarefa."}, {"title": "Atualiza por época", "text": "Em campanhas sazonais, acrescenta uma linha com a oferta do momento e a data de fim."}]}'::jsonb, '{"problem": "Every time you ask for a text, the AI starts from scratch. It doesn''t know what you sell, what it costs, who your customers are or how you talk to them. The result: copy that sounds like another brand, promises you don''t make and a tone that isn''t yours.", "steps": [{"title": "Write your business profile", "text": "Five lines: what you sell, to whom, where, what makes you different and your typical price. Example: \"Physiotherapy clinic in Leeds. Clients: amateur athletes and people with back pain. Difference: a 60-minute assessment on the first visit. Price: 50 pounds per session.\""}, {"title": "Define your tone with examples", "text": "Instead of \"professional tone\", give three words and one real sentence of yours: \"Friendly, direct, no hype. Example: Book your assessment, we''ll take care of the rest.\""}, {"title": "Say what never to say", "text": "List what''s off-limits: promised results, discounts you don''t offer, words you hate. The AI respects limits once it knows them."}], "before": {"prompt": "Write an email to my customers about the November promotion.", "note": "The AI will invent the promotion, the tone and maybe even the type of business."}, "after": {"prompt": "Context: physiotherapy clinic in Leeds. Clients: amateur athletes and people with back pain. Tone: friendly, direct, no hype. Never promise cures or guaranteed results. Task: write a short email (up to 120 words) announcing 15% off the initial assessment throughout November. Subject line under 50 characters. End by inviting readers to book by phone. Plain text.", "note": "The business profile prevents made-up details and keeps your brand voice in every text."}, "try": {"intro": "Build your business profile here and open it in Create Prompt. Then save it to your Library to reuse.", "target": "builder", "template": "Business context: {{business}}, in {{location}}. Customers: {{audience}}. What sets us apart: {{offer}}. Tone: {{tone}}. Never say: {{notes}}. Task: {{task}}. Deliver as plain text.", "labels": {"notes": ["What never to say", "e.g. promising results"], "offer": ["What sets you apart", "e.g. same-day delivery"], "task": ["Task", "e.g. an email announcing the November offer"]}}, "checklist": ["The profile says what I sell and to whom", "I included location and price where it matters", "The tone has concrete words and a real example", "I listed what never to say", "I saved the profile to reuse"], "tips": [{"title": "One profile, many uses", "text": "The same profile works for posts, emails, review replies and ads. Only the task changes."}, {"title": "Refresh it seasonally", "text": "For seasonal campaigns, add one line with the current offer and its end date."}]}'::jsonb from public.learn_lessons where slug = 'contexto-negocio'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
