values ('formato-certo', 'fundamentos', null, 3, true, 4, 'basico', 'Pedir o formato certo', 'Ask for the right format', 'Como receber o texto já no tamanho, estrutura e formato de que precisas, sem limpezas depois.', 'How to get text in the length, structure and format you need, with no clean-up afterwards.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "A IA devolve um texto com títulos, asteriscos e listas quando só querias um parágrafo para colar no WhatsApp. Ou escreve 600 palavras quando o anúncio aceita 125 caracteres. Perdes tempo a cortar e a limpar.", "steps": [{"title": "Diz onde o texto vai ser usado", "text": "\"Para colar no Google Business\", \"para uma legenda de Reels\", \"para um SMS\". O destino já diz muito sobre o tamanho e o estilo."}, {"title": "Dá números", "text": "Limites concretos funcionam melhor do que \"curto\": até 150 caracteres, 3 frases, 5 pontos, 80 palavras. Se o limite é rígido, diz que é rígido."}, {"title": "Pede texto simples e a estrutura exata", "text": "\"Texto simples, sem formatação nem asteriscos\". Se precisas de várias partes, enumera-as: \"Assunto, depois corpo, depois uma linha de despedida\"."}], "before": {"prompt": "Faz-me um texto para o anúncio do Facebook sobre o curso de inglês.", "note": "Sem tamanho nem estrutura: pode vir um texto longo, com títulos e formatação que o Facebook não mostra."}, "after": {"prompt": "Escreve o texto de um anúncio do Facebook para um curso de inglês para adultos em Lisboa, às terças e quintas à noite. Estrutura: 1 frase de abertura com uma pergunta, 2 frases com os benefícios, 1 frase com o apelo à ação. Máximo 125 caracteres no texto principal e um título até 40 caracteres. Texto simples, sem formatação. Dá-me 3 versões.", "note": "Destino, números e estrutura. Recebes 3 versões prontas a testar."}, "try": {"intro": "Escolhe o destino e os limites e abre no Otimizador para ver a pontuação.", "target": "optimizer", "template": "Escreve {{tarefa}} para publicar em {{plataforma}}. Estrutura: abertura com uma pergunta, 2 frases de benefícios, 1 apelo à ação. Máximo {{numero}} caracteres. Texto simples, sem formatação nem asteriscos. Dá-me 3 versões numeradas.", "labels": {"numero": ["Máximo de caracteres", "Ex.: 150"], "tarefa": ["O que queres escrever", "Ex.: o texto de um anúncio"]}}, "checklist": ["Disse onde o texto vai ser publicado", "Pus limites com números", "Descrevi a estrutura em partes", "Pedi texto simples quando vou colar noutro sítio", "Pedi mais de uma versão para escolher"], "tips": [{"title": "Tabelas para comparar", "text": "Para comparar opções (preços, fornecedores), pede uma tabela com as colunas que queres. Depois colas numa folha de cálculo."}, {"title": "Versões A e B", "text": "Pedir 3 versões custa o mesmo que pedir 1 e dá-te escolha."}]}'::jsonb, '{"problem": "The AI gives you headings, asterisks and bullet points when you only wanted one paragraph for WhatsApp. Or it writes 600 words when the ad allows 125 characters. You waste time cutting and cleaning.", "steps": [{"title": "Say where the text will be used", "text": "\"To paste into Google Business\", \"for a Reels caption\", \"for an SMS\". The destination already says a lot about length and style."}, {"title": "Use numbers", "text": "Concrete limits beat \"short\": under 150 characters, 3 sentences, 5 points, 80 words. If the limit is strict, say it''s strict."}, {"title": "Ask for plain text and the exact structure", "text": "\"Plain text, no formatting or asterisks.\" If you need several parts, list them: \"Subject, then body, then a one-line sign-off.\""}], "before": {"prompt": "Write me some text for a Facebook ad about the English course.", "note": "No length or structure: you may get a long text with headings and formatting Facebook won''t display."}, "after": {"prompt": "Write Facebook ad copy for an evening Spanish course for adults in Manchester, Tuesdays and Thursdays. Structure: 1 opening question, 2 sentences on the benefits, 1 call to action. Maximum 125 characters in the primary text and a headline under 40 characters. Plain text, no formatting. Give me 3 versions.", "note": "Destination, numbers and structure. You get 3 versions ready to test."}, "try": {"intro": "Pick the destination and limits, then open it in the Optimizer to see the score.", "target": "optimizer", "template": "Write {{task}} to publish on {{platform}}. Structure: an opening question, 2 sentences on the benefits, 1 call to action. Maximum {{number}} characters. Plain text, no formatting or asterisks. Give me 3 numbered versions.", "labels": {"number": ["Character limit", "e.g. 150"], "task": ["What you want written", "e.g. ad copy"]}}, "checklist": ["I said where the text will be published", "I set limits with numbers", "I described the structure in parts", "I asked for plain text because I''m pasting it elsewhere", "I asked for more than one version"], "tips": [{"title": "Tables for comparisons", "text": "To compare options (prices, suppliers), ask for a table with the columns you want, then paste it into a spreadsheet."}, {"title": "Versions A and B", "text": "Asking for 3 versions costs the same as asking for 1 and gives you a choice."}]}'::jsonb from public.learn_lessons where slug = 'formato-certo'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('iterar', 'fundamentos', null, 4, true, 5, 'basico', 'Iterar: do primeiro rascunho ao texto final', 'Iterate: from first draft to final copy', 'O primeiro resultado raramente é o melhor. Três pedidos de seguimento que melhoram qualquer texto em minutos.', 'The first result is rarely the best. Three follow-up requests that improve any text in minutes.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Recebes um texto razoável, mas não perfeito, e começas a reescrevê-lo à mão. Ou desistes e pedes tudo de novo, perdendo o que estava bem. A conversa com a IA é o teu melhor editor, se souberes o que pedir.", "steps": [{"title": "Diz o que está bem e o que mudar", "text": "\"Mantém a estrutura e a abertura. Torna o final mais direto e corta 30% do texto.\" Ser específico sobre o que manter evita perder o que já funcionava."}, {"title": "Pede variações com um eixo claro", "text": "Em vez de \"outra versão\", diz a diferença: \"mais curta\", \"mais formal\", \"com foco no preço\", \"para quem nunca nos comprou\"."}, {"title": "Pede uma revisão crítica", "text": "\"Revê o texto como um cliente cético: o que não é claro, o que soa a exagero?\" Depois pede que aplique as correções."}], "before": {"prompt": "Não gostei, faz outro.", "note": "A IA não sabe o que falhou e pode piorar o que estava bem."}, "after": {"prompt": "Mantém a abertura e a lista de serviços. Corta o texto para metade, troca \"soluções inovadoras\" por exemplos concretos e termina com uma pergunta ao leitor. Depois revê-o como um cliente cético e diz-me em 3 pontos o que ainda pode soar a exagero.", "note": "Instruções de edição claras e uma revisão crítica no fim. Duas mensagens e tens o texto final."}, "try": {"intro": "Cola um rascunho teu e abre no Otimizador: ele sugere versões e explica cada alteração.", "target": "optimizer", "template": "Aqui está o meu rascunho: {{rascunho}}. Mantém {{referencia}}. Muda: {{instrucoes}}. Depois revê o texto como um cliente cético e lista em 3 pontos o que ainda não está claro. Texto simples.", "labels": {"referencia": ["O que manter", "Ex.: a abertura e a lista de serviços"], "instrucoes": ["O que mudar", "Ex.: cortar para metade e terminar com uma pergunta"]}}, "checklist": ["Disse o que manter", "Disse o que mudar, com detalhe", "Pedi variações com uma diferença clara", "Pedi uma revisão crítica", "Comparei as versões antes de escolher"], "tips": [{"title": "Uma mudança de cada vez", "text": "Se pedes cinco mudanças ao mesmo tempo, é difícil perceber qual melhorou o texto. Duas ou três por mensagem é o ideal."}, {"title": "Usa o Otimizador", "text": "O Otimizador do PromptForge dá-te uma pontuação e explica cada melhoria. É uma forma rápida de iterar o próprio prompt."}]}'::jsonb, '{"problem": "You get a decent but imperfect text and start rewriting it by hand. Or you give up and ask again from scratch, losing what was good. The conversation with the AI is your best editor, if you know what to ask for.", "steps": [{"title": "Say what works and what to change", "text": "\"Keep the structure and the opening. Make the ending more direct and cut 30% of the text.\" Saying what to keep stops you losing what already worked."}, {"title": "Ask for variations along one clear axis", "text": "Instead of \"another version\", name the difference: \"shorter\", \"more formal\", \"focus on price\", \"for people who''ve never bought from us\"."}, {"title": "Ask for a critical review", "text": "\"Review this as a sceptical customer: what''s unclear, what sounds like hype?\" Then ask it to apply the fixes."}], "before": {"prompt": "Don''t like it, do another one.", "note": "The AI doesn''t know what failed and may make the good parts worse."}, "after": {"prompt": "Keep the opening and the list of services. Cut the text in half, replace \"innovative solutions\" with concrete examples and end with a question to the reader. Then review it as a sceptical customer and tell me in 3 points what could still sound like hype.", "note": "Clear editing instructions plus a critical review. Two messages and you have the final copy."}, "try": {"intro": "Paste one of your drafts and open it in the Optimizer: it suggests versions and explains every change.", "target": "optimizer", "template": "Here is my draft: {{draft}}. Keep {{reference}}. Change: {{instructions}}. Then review the text as a sceptical customer and list in 3 points what is still unclear. Plain text.", "labels": {"reference": ["What to keep", "e.g. the opening and the list of services"], "instructions": ["What to change", "e.g. cut it in half and end with a question"]}}, "checklist": ["I said what to keep", "I said what to change, in detail", "I asked for variations with one clear difference", "I asked for a critical review", "I compared versions before choosing"], "tips": [{"title": "One change at a time", "text": "Ask for five changes at once and it''s hard to tell which one helped. Two or three per message is ideal."}, {"title": "Use the Optimizer", "text": "PromptForge''s Optimizer scores your prompt and explains each improvement. It''s a quick way to iterate on the prompt itself."}]}'::jsonb from public.learn_lessons where slug = 'iterar'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('erros-comuns', 'fundamentos', null, 5, true, 6, 'basico', 'Erros comuns, factos inventados e dados de clientes', 'Common mistakes, made-up facts and customer data', 'Como evitar que a IA invente números, como verificar o que escreve e o que nunca deves colar num prompt.', 'How to stop the AI inventing numbers, how to check what it writes and what you should never paste into a prompt.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "A IA escreve com confiança mesmo quando não sabe: inventa estatísticas, moradas, preços, leis e testemunhos. E muitos utilizadores colam emails de clientes com nomes, NIF e telefones sem pensar duas vezes. Os dois erros custam caro: credibilidade e RGPD.", "steps": [{"title": "Dá tu os factos", "text": "Preços, datas, moradas, horários e números têm de vir de ti. Acrescenta: \"Usa apenas os dados que te dou. Se faltar informação, escreve [A CONFIRMAR] em vez de inventar.\""}, {"title": "Verifica antes de publicar", "text": "Lê tudo o que é factual: números, nomes, prazos, referências legais. Pede à IA: \"Lista todas as afirmações factuais do texto para eu confirmar.\""}, {"title": "Anonimiza dados pessoais", "text": "Antes de colar uma mensagem de cliente, troca nomes, emails, telefones, NIF e moradas por [CLIENTE], [EMAIL], etc. A IA não precisa deles para ajudar."}], "before": {"prompt": "Escreve um post a dizer que somos a clínica mais bem avaliada do Porto e que 98% dos pacientes recomendam. Responde também a este email da Maria Silva, NIF 123456789, telefone 912345678: ...", "note": "Afirmações que não podes provar e dados pessoais desnecessários num prompt."}, "after": {"prompt": "Escreve um post sobre a nossa clínica no Porto. Dados reais: 4,8 estrelas no Google com 212 avaliações, aberta desde 2015. Não inventes estatísticas nem testemunhos. Se faltar algum dado, escreve [A CONFIRMAR]. Depois responde a este email de [CLIENTE], que pede para remarcar a consulta de [DATA]: ...", "note": "Factos dados por ti, regra contra invenções e dados pessoais anonimizados."}, "try": {"intro": "Usa este modelo sempre que o texto tiver factos. Abre no Criar Prompt e completa.", "target": "builder", "template": "Escreve {{tarefa}}. Usa apenas estes dados: {{dados}}. Não inventes números, testemunhos, leis nem prémios. Se faltar informação, escreve [A CONFIRMAR]. No fim, lista as afirmações factuais do texto para eu verificar. Texto simples.", "labels": {"tarefa": ["O que queres escrever", "Ex.: um post sobre a clínica"], "dados": ["Os teus dados reais", "Ex.: 4,8 estrelas, 212 avaliações, desde 2015"]}}, "checklist": ["Todos os números e datas vieram de mim", "Pedi [A CONFIRMAR] em vez de invenções", "Verifiquei nomes, preços e prazos antes de publicar", "Anonimizei nomes, contactos e NIF", "Não colei documentos confidenciais sem necessidade"], "tips": [{"title": "Cuidado com leis e saúde", "text": "Em temas legais, fiscais ou de saúde, usa a IA para o rascunho e confirma sempre com uma fonte oficial ou um profissional."}, {"title": "Testemunhos só reais", "text": "Nunca peças à IA para criar avaliações ou testemunhos. Usa frases reais de clientes, com autorização."}]}'::jsonb, '{"problem": "AI writes confidently even when it doesn''t know: it invents statistics, addresses, prices, laws and testimonials. And many people paste customer emails with names, tax numbers and phone numbers without a second thought. Both mistakes are costly: your credibility and GDPR compliance.", "steps": [{"title": "Supply the facts yourself", "text": "Prices, dates, addresses, opening hours and figures must come from you. Add: \"Use only the data I give you. If something is missing, write [TO CONFIRM] instead of making it up.\""}, {"title": "Check before publishing", "text": "Read everything factual: numbers, names, deadlines, legal references. Ask the AI: \"List every factual claim in the text so I can confirm it.\""}, {"title": "Anonymise personal data", "text": "Before pasting a customer message, replace names, emails, phone numbers, tax IDs and addresses with [CUSTOMER], [EMAIL] and so on. The AI doesn''t need them to help."}], "before": {"prompt": "Write a post saying we''re the best-rated clinic in Manchester and 98% of patients recommend us. Also reply to this email from Mary Smith, phone 07700 900123, who lives at 12 High Street: ...", "note": "Claims you can''t back up and personal data the prompt doesn''t need."}, "after": {"prompt": "Write a post about our clinic in Manchester. Real data: 4.8 stars on Google from 212 reviews, open since 2015. Don''t invent statistics or testimonials. If anything is missing, write [TO CONFIRM]. Then reply to this email from [CUSTOMER], who wants to move their appointment on [DATE]: ...", "note": "Facts from you, a rule against inventions and personal data anonymised."}, "try": {"intro": "Use this template whenever the text contains facts. Open it in Create Prompt and complete it.", "target": "builder", "template": "Write {{task}}. Use only this data: {{data}}. Don''t invent numbers, testimonials, laws or awards. If information is missing, write [TO CONFIRM]. At the end, list the factual claims in the text so I can check them. Plain text.", "labels": {"task": ["What you want written", "e.g. a post about the clinic"], "data": ["Your real data", "e.g. 4.8 stars, 212 reviews, since 2015"]}}, "checklist": ["Every number and date came from me", "I asked for [TO CONFIRM] instead of inventions", "I checked names, prices and deadlines before publishing", "I anonymised names, contact details and IDs", "I didn''t paste confidential documents unnecessarily"], "tips": [{"title": "Careful with law and health", "text": "On legal, tax or health topics, use AI for the draft and always confirm with an official source or a professional."}, {"title": "Real testimonials only", "text": "Never ask AI to create reviews or testimonials. Use real customer quotes, with permission."}]}'::jsonb from public.learn_lessons where slug = 'erros-comuns'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('ganchos-reels', 'setor', 'marketing', 101, true, 5, 'intermedio', 'Ganchos e legendas para TikTok e Reels', 'Hooks and captions for TikTok and Reels', 'Como pedir ganchos que prendem nos primeiros 2 segundos e legendas que levam à ação.', 'How to ask for hooks that grab attention in the first 2 seconds and captions that drive action.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Os vídeos curtos vivem ou morrem nos primeiros segundos. Pedir \"ideias para um Reel\" dá ganchos batidos (\"Sabias que...?\") e legendas longas que ninguém lê. Precisas de variedade, de ângulos diferentes e de textos à medida da plataforma.", "steps": [{"title": "Define o espectador e a dor", "text": "Quem vai ver e o que o incomoda: \"donos de cafés que perdem clientes ao fim de semana\". Um gancho bom fala de um problema que a pessoa reconhece."}, {"title": "Pede ganchos por tipo", "text": "Pede 10 ganchos divididos por estilo: pergunta, erro comum, número, contraste antes/depois, opinião polémica. Assim tens ângulos diferentes para testar."}, {"title": "Junta legenda e apelo à ação", "text": "Para os 2 melhores, pede legenda até 150 caracteres, 3 a 5 hashtags relevantes e um apelo à ação simples (guardar, comentar, visitar)."}], "before": {"prompt": "Dá-me ideias para um Reel sobre o meu café.", "note": "Sem público, sem dor, sem tipo de gancho. Recebes ideias genéricas."}, "after": {"prompt": "Sou dono de um café de especialidade em Coimbra. Público: estudantes e jovens profissionais que trabalham com o portátil. Escreve 10 ganchos para Reels (até 8 palavras cada), 2 de cada tipo: pergunta, erro comum, número, antes/depois e opinião polémica. Depois, para os 2 mais fortes, escreve uma legenda até 150 caracteres, 4 hashtags locais e um apelo para guardar o vídeo. Texto simples.", "note": "Público, tipos de gancho e um pacote completo para publicar."}, "try": {"intro": "Preenche e abre no Criar Prompt. Depois testa os ganchos com o Teste A/B.", "target": "builder", "template": "O meu negócio: {{negocio}}. Público: {{publico}}. Tema do vídeo: {{tema}}. Escreve 10 ganchos para {{plataforma}} (até 8 palavras), 2 de cada tipo: pergunta, erro comum, número, antes/depois, opinião polémica. Para os 2 melhores, escreve legenda até 150 caracteres, 4 hashtags e um apelo à ação. Texto simples.", "labels": {"tema": ["Tema do vídeo", "Ex.: como escolher café em grão"], "plataforma": ["Plataforma", "Ex.: Instagram Reels"]}}, "checklist": ["Defini o espectador e a dor dele", "Pedi ganchos por tipo", "Os ganchos têm limite de palavras", "Pedi legenda, hashtags e apelo à ação", "Escolhi 2 para testar"], "tips": [{"title": "O gancho é falado e escrito", "text": "Usa o mesmo gancho no texto no ecrã e na primeira frase dita. Reforça a mensagem para quem vê sem som."}, {"title": "Recicla o que resulta", "text": "Quando um gancho funciona, pede 5 variações com o mesmo ângulo para os próximos vídeos."}]}'::jsonb, '{"problem": "Short videos live or die in the first seconds. Asking for \"Reel ideas\" gets you tired hooks (\"Did you know...?\") and long captions nobody reads. You need variety, different angles and copy that fits the platform.", "steps": [{"title": "Define the viewer and their pain", "text": "Who''s watching and what bothers them: \"café owners who lose customers at weekends\". A good hook names a problem people recognise."}, {"title": "Ask for hooks by type", "text": "Ask for 10 hooks split by style: question, common mistake, number, before/after contrast, hot take. That gives you different angles to test."}, {"title": "Add caption and call to action", "text": "For the top 2, ask for a caption under 150 characters, 3 to 5 relevant hashtags and one simple call to action (save, comment, visit)."}], "before": {"prompt": "Give me ideas for a Reel about my café.", "note": "No audience, no pain point, no hook type. You get generic ideas."}, "after": {"prompt": "I run a specialty coffee shop in Brighton. Audience: students and young professionals who work on laptops. Write 10 Reels hooks (up to 8 words each), 2 of each type: question, common mistake, number, before/after and hot take. Then, for the 2 strongest, write a caption under 150 characters, 4 local hashtags and a call to save the video. Plain text.", "note": "Audience, hook types and a complete package ready to post."}, "try": {"intro": "Fill in the fields and open in Create Prompt. Then test the hooks with A/B Testing.", "target": "builder", "template": "My business: {{business}}. Audience: {{audience}}. Video topic: {{topic}}. Write 10 hooks for {{platform}} (up to 8 words), 2 of each type: question, common mistake, number, before/after, hot take. For the best 2, write a caption under 150 characters, 4 hashtags and a call to action. Plain text.", "labels": {"topic": ["Video topic", "e.g. how to choose coffee beans"], "platform": ["Platform", "e.g. Instagram Reels"]}}, "checklist": ["I defined the viewer and their pain", "I asked for hooks by type", "The hooks have a word limit", "I asked for caption, hashtags and a call to action", "I picked 2 to test"], "tips": [{"title": "Say it and show it", "text": "Use the same hook as on-screen text and as the first spoken line. It lands even for people watching on mute."}, {"title": "Recycle winners", "text": "When a hook works, ask for 5 variations on the same angle for your next videos."}]}'::jsonb from public.learn_lessons where slug = 'ganchos-reels'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('anuncios-ab', 'setor', 'marketing', 102, false, 6, 'intermedio', 'Anúncios com teste A/B', 'Ads with A/B testing', 'Gera variações de anúncios com uma única diferença entre elas, para saberes o que realmente funciona.', 'Generate ad variations that differ in just one thing, so you learn what actually works.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Muitas campanhas testam anúncios que diferem em tudo: título, imagem, oferta e público. Quando um ganha, não sabes porquê. A IA pode gerar dezenas de variações, mas sem método só aumenta o ruído.", "steps": [{"title": "Escolhe uma variável a testar", "text": "Testa uma coisa de cada vez: a promessa principal, a oferta, o apelo à ação ou o tom. Diz à IA qual é a variável e o que fica igual."}, {"title": "Pede pares controlados", "text": "\"Escreve a versão A com foco em poupar tempo e a versão B com foco em poupar dinheiro. Mesmo tamanho, mesmo apelo à ação.\""}, {"title": "Define o critério de vitória", "text": "Antes de lançar, decide a métrica (cliques, contactos, compras) e o prazo. Pede à IA uma hipótese para cada versão, para aprenderes com o resultado."}], "before": {"prompt": "Faz 10 anúncios diferentes para o meu ginásio.", "note": "Dez variações sem controlo: não vais saber o que fez a diferença."}, "after": {"prompt": "Ginásio de bairro em Setúbal, mensalidade 29 euros, sem fidelização. Variável a testar: a promessa principal. Escreve a versão A com foco em \"sem fidelização\" e a versão B com foco em \"aulas de grupo incluídas\". Iguais em tudo o resto: texto principal até 125 caracteres, título até 40, apelo \"Marca a tua aula grátis\". Para cada uma, escreve numa linha a hipótese que estamos a testar. Texto simples.", "note": "Uma só variável, tudo o resto igual e uma hipótese clara. O resultado ensina-te algo."}, "try": {"intro": "Preenche e abre no Criar Prompt. Depois compara as duas versões no Teste A/B.", "target": "builder", "template": "Negócio: {{negocio}}. Oferta: {{oferta}}. Variável a testar: {{tema}}. Escreve a versão A com foco em {{opcao_a}} e a versão B com foco em {{opcao_b}}. Tudo o resto igual: texto até 125 caracteres, título até 40, apelo à ação \"{{acao}}\". Para cada versão, escreve a hipótese numa linha. Texto simples.", "labels": {"tema": ["O que vais testar", "Ex.: a promessa principal"], "opcao_a": ["Foco da versão A", "Ex.: sem fidelização"], "opcao_b": ["Foco da versão B", "Ex.: aulas de grupo incluídas"], "acao": ["Apelo à ação", "Ex.: Marca a tua aula grátis"]}}, "checklist": ["Escolhi uma única variável", "O resto do anúncio é igual nas duas versões", "Respeitei os limites da plataforma", "Escrevi uma hipótese por versão", "Defini a métrica e o prazo antes de lançar"], "tips": [{"title": "Orçamento igual", "text": "Dá o mesmo orçamento e o mesmo público às duas versões. Caso contrário, o teste não é justo."}, {"title": "Guarda os vencedores", "text": "Guarda os anúncios vencedores na Biblioteca, com a métrica no título. Ao fim de uns meses tens um manual do que funciona com o teu público."}]}'::jsonb, '{"problem": "Many campaigns test ads that differ in everything: headline, image, offer and audience. When one wins, you don''t know why. AI can generate dozens of variations, but without a method it only adds noise.", "steps": [{"title": "Pick one variable to test", "text": "Test one thing at a time: the main promise, the offer, the call to action or the tone. Tell the AI which variable it is and what stays the same."}, {"title": "Ask for controlled pairs", "text": "\"Write version A focused on saving time and version B focused on saving money. Same length, same call to action.\""}, {"title": "Set the success metric", "text": "Before launching, choose the metric (clicks, leads, sales) and the duration. Ask the AI for a hypothesis per version so you learn from the result."}], "before": {"prompt": "Write 10 different ads for my gym.", "note": "Ten uncontrolled variations: you won''t know what made the difference."}, "after": {"prompt": "Neighbourhood gym in Leicester, 25 pounds a month, no contract. Variable to test: the main promise. Write version A focused on \"no contract\" and version B focused on \"group classes included\". Identical otherwise: primary text up to 125 characters, headline up to 40, call to action \"Book your free class\". For each one, write the hypothesis we''re testing in one line. Plain text.", "note": "One variable, everything else the same and a clear hypothesis. The result teaches you something."}, "try": {"intro": "Fill in the fields and open in Create Prompt. Then compare both versions in A/B Testing.", "target": "builder", "template": "Business: {{business}}. Offer: {{offer}}. Variable to test: {{topic}}. Write version A focused on {{option_a}} and version B focused on {{option_b}}. Everything else identical: text up to 125 characters, headline up to 40, call to action \"{{action}}\". For each version, write the hypothesis in one line. Plain text.", "labels": {"topic": ["What you are testing", "e.g. the main promise"], "option_a": ["Version A focus", "e.g. no contract"], "option_b": ["Version B focus", "e.g. group classes included"], "action": ["Call to action", "e.g. Book your free class"]}}, "checklist": ["I chose a single variable", "Everything else is identical in both versions", "I respected the platform limits", "I wrote one hypothesis per version", "I set the metric and duration before launch"], "tips": [{"title": "Same budget", "text": "Give both versions the same budget and audience, otherwise the test isn''t fair."}, {"title": "Keep the winners", "text": "Save winning ads in your Library with the metric in the title. After a few months you''ll have a playbook of what works with your audience."}]}'::jsonb from public.learn_lessons where slug = 'anuncios-ab'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('avaliacoes-google', 'setor', 'pme', 111, true, 5, 'basico', 'Responder a avaliações no Google', 'Replying to Google reviews', 'Respostas rápidas, pessoais e profissionais a avaliações boas e más, que também ajudam quem ainda não te conhece.', 'Quick, personal and professional replies to good and bad reviews that also reassure people who don''t know you yet.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Responder a avaliações leva tempo e as respostas acabam todas iguais (\"Obrigado pela preferência!\"). Nas negativas, o risco é responder a quente. E quem lê as respostas não é só o autor: são os teus próximos clientes.", "steps": [{"title": "Cola a avaliação e dá contexto", "text": "Cola o texto da avaliação (sem o nome completo) e diz o que sabes: \"o atraso foi real, tivemos duas pessoas doentes\"."}, {"title": "Define a estrutura da resposta", "text": "Agradecer, referir um detalhe concreto da avaliação, explicar ou corrigir (nas negativas), convidar a voltar ou a falar diretamente. Até 80 palavras."}, {"title": "Regras de tom", "text": "Sem desculpas genéricas, sem discutir, sem prometer o que não podes cumprir. Nas negativas, oferece um contacto direto para resolver fora do público."}], "before": {"prompt": "Responde a esta avaliação: \"Esperei 40 minutos pela comida.\"", "note": "Sem contexto nem regras: arriscas uma resposta defensiva ou vazia."}, "after": {"prompt": "Sou gerente de um restaurante em Viseu. Avaliação de 2 estrelas: \"Esperei 40 minutos pela comida, mas o bacalhau estava ótimo.\" Contexto: nesse sábado tínhamos a cozinha com menos uma pessoa. Escreve uma resposta até 80 palavras: agradece, reconhece a espera sem desculpas genéricas, valoriza o elogio ao bacalhau, diz o que mudámos (reforço ao fim de semana) e convida a voltar. Assina como \"Rui, gerente\". Texto simples.", "note": "Contexto real, estrutura definida e um tom que tranquiliza futuros clientes."}, "try": {"intro": "Cola uma avaliação real e abre no Criar Prompt.", "target": "builder", "template": "Sou {{funcao}} de {{negocio}}. Avaliação de {{numero}} estrelas: {{avaliacao}}. Contexto: {{contexto}}. Escreve uma resposta até 80 palavras: agradece, refere um detalhe concreto, explica sem desculpas genéricas, diz o que vamos fazer e convida a voltar ou a falar connosco diretamente. Assina como {{nome}}. Texto simples.", "labels": {"numero": ["Estrelas", "Ex.: 2"], "nome": ["Assinatura", "Ex.: Rui, gerente"], "contexto": ["O que aconteceu", "Ex.: tínhamos menos uma pessoa na cozinha"]}}, "checklist": ["Retirei o nome completo e dados do cliente", "Dei o contexto real", "A resposta refere um detalhe da avaliação", "Nas negativas, ofereci contacto direto", "Revi antes de publicar"], "tips": [{"title": "Responde a todas", "text": "Responde também às de 5 estrelas, com uma frase personalizada. Mostra a quem lê que há pessoas por trás do negócio."}, {"title": "Palavras-chave com naturalidade", "text": "Mencionar o prato, o serviço ou a localidade de forma natural ajuda quem pesquisa no Google."}]}'::jsonb, '{"problem": "Replying to reviews takes time, and the replies all end up the same (\"Thanks for your business!\"). With negative ones, the risk is replying in the heat of the moment. And the reviewer isn''t your only reader: your next customers read the replies too.", "steps": [{"title": "Paste the review and give context", "text": "Paste the review text (without the full name) and say what you know: \"the delay was real, two staff members were off sick\"."}, {"title": "Set the reply structure", "text": "Thank them, mention a concrete detail from the review, explain or fix (for negative ones), invite them back or to talk directly. Up to 80 words."}, {"title": "Set tone rules", "text": "No generic apologies, no arguing, no promises you can''t keep. For negative reviews, offer a direct contact to sort it out away from the public eye."}], "before": {"prompt": "Reply to this review: \"I waited 40 minutes for my food.\"", "note": "No context or rules: you risk a defensive or empty reply."}, "after": {"prompt": "I manage a restaurant in York. 2-star review: \"I waited 40 minutes for my food, but the fish was excellent.\" Context: that Saturday the kitchen was one person short. Write a reply of up to 80 words: thank them, acknowledge the wait without a generic apology, appreciate the praise for the fish, say what we changed (extra weekend staff) and invite them back. Sign off as \"Tom, manager\". Plain text.", "note": "Real context, a set structure and a tone that reassures future customers."}, "try": {"intro": "Paste a real review and open in Create Prompt.", "target": "builder", "template": "I am the {{role}} at {{business}}. {{number}}-star review: {{review}}. Context: {{context}}. Write a reply of up to 80 words: thank them, mention a concrete detail, explain without generic apologies, say what we''ll do and invite them back or to contact us directly. Sign off as {{name}}. Plain text.", "labels": {"number": ["Stars", "e.g. 2"], "name": ["Sign-off", "e.g. Tom, manager"], "context": ["What happened", "e.g. the kitchen was one person short"]}}, "checklist": ["I removed the full name and personal details", "I gave the real context", "The reply mentions a detail from the review", "For negative reviews, I offered a direct contact", "I proofread before posting"], "tips": [{"title": "Reply to all of them", "text": "Reply to 5-star reviews too, with one personal line. It shows readers there are real people behind the business."}, {"title": "Keywords, naturally", "text": "Mentioning the dish, the service or the town naturally helps people searching on Google."}]}'::jsonb from public.learn_lessons where slug = 'avaliacoes-google'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('newsletter-mensal', 'setor', 'pme', 112, false, 6, 'intermedio', 'Uma newsletter mensal que se lê', 'A monthly newsletter people actually read', 'Um modelo fixo de newsletter curta que mantém os clientes por perto sem te tomar uma tarde por mês.', 'A fixed, short newsletter template that keeps customers close without eating an afternoon every month.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "A newsletter fica sempre para depois, e quando sai é longa, cheia de novidades sem interesse para o cliente e com uma taxa de abertura baixa. O problema não é escrever, é não ter um formato fixo nem um motivo claro para o cliente abrir.", "steps": [{"title": "Fixa um formato curto", "text": "Sempre as mesmas 4 partes: assunto, 1 novidade útil, 1 dica ou bastidores, 1 oferta ou convite. Até 200 palavras. O cliente habitua-se e lê."}, {"title": "Dá a matéria-prima", "text": "Cola em tópicos o que aconteceu no mês: produtos novos, datas, uma pergunta frequente de clientes, a oferta. A IA organiza; tu dás os factos."}, {"title": "Pede 3 assuntos e uma versão curta", "text": "Pede 3 linhas de assunto com estilos diferentes (benefício, curiosidade, urgência) e uma versão de 2 frases para enviar também por WhatsApp ou SMS."}], "before": {"prompt": "Escreve a newsletter de dezembro da minha loja.", "note": "A IA não sabe o que aconteceu nem o que queres que o cliente faça."}, "after": {"prompt": "Loja de produtos naturais em Faro. Newsletter de dezembro, até 200 palavras, em 4 partes: 1) novidade: chegaram os cabazes de Natal (25 e 40 euros); 2) dica: como escolher mel cru; 3) bastidores: a nova parceria com um produtor de Monchique; 4) convite: 10% nos cabazes até dia 15 com o código NATAL10. Tom caloroso e simples. Dá-me 3 assuntos (benefício, curiosidade, urgência) e uma versão de 2 frases para WhatsApp. Texto simples.", "note": "Formato fixo, factos reais e versões para vários canais num só pedido."}, "try": {"intro": "Preenche os tópicos do mês e abre no Criar Prompt.", "target": "builder", "template": "Negócio: {{negocio}}. Newsletter de {{data}}, até 200 palavras, em 4 partes: novidade: {{novidades}}; dica útil: {{tema}}; bastidores: {{contexto}}; oferta ou convite: {{oferta}}. Tom {{tom}}. Dá-me 3 linhas de assunto (benefício, curiosidade, urgência) e uma versão de 2 frases para WhatsApp. Texto simples.", "labels": {"data": ["Mês", "Ex.: dezembro"], "tema": ["Dica útil", "Ex.: como escolher mel cru"], "contexto": ["Bastidores", "Ex.: nova parceria com um produtor local"], "oferta": ["Oferta ou convite", "Ex.: 10% nos cabazes até dia 15"]}}, "checklist": ["Usei o formato fixo de 4 partes", "Todos os factos e preços vieram de mim", "Tenho 3 assuntos para escolher", "Há uma única ação clara para o cliente", "Fiz a versão curta para WhatsApp ou SMS"], "tips": [{"title": "Mesmo dia, mesma hora", "text": "Enviar sempre no mesmo dia do mês cria hábito, tanto em ti como nos clientes."}, {"title": "Recolhe perguntas", "text": "As perguntas que os clientes fazem ao balcão são o melhor tema para a dica do mês."}]}'::jsonb, '{"problem": "The newsletter keeps getting postponed, and when it goes out it''s long, full of news customers don''t care about, and barely opened. The problem isn''t writing; it''s having no fixed format and no clear reason for customers to open it.", "steps": [{"title": "Fix a short format", "text": "Always the same 4 parts: subject, 1 useful update, 1 tip or behind-the-scenes, 1 offer or invitation. Up to 200 words. Customers get used to it and read it."}, {"title": "Supply the raw material", "text": "Paste bullet points of what happened this month: new products, dates, a frequent customer question, the offer. The AI organises; you provide the facts."}, {"title": "Ask for 3 subjects and a short version", "text": "Ask for 3 subject lines in different styles (benefit, curiosity, urgency) and a 2-sentence version to send by WhatsApp or SMS too."}], "before": {"prompt": "Write my shop''s December newsletter.", "note": "The AI doesn''t know what happened or what you want customers to do."}, "after": {"prompt": "Health food shop in Bath. December newsletter, up to 200 words, in 4 parts: 1) update: Christmas hampers are in (25 and 40 pounds); 2) tip: how to choose raw honey; 3) behind the scenes: our new partnership with a Somerset beekeeper; 4) offer: 10% off hampers until the 15th with code XMAS10. Warm, simple tone. Give me 3 subject lines (benefit, curiosity, urgency) and a 2-sentence version for WhatsApp. Plain text.", "note": "Fixed format, real facts and versions for several channels in a single request."}, "try": {"intro": "Fill in this month''s topics and open in Create Prompt.", "target": "builder", "template": "Business: {{business}}. Newsletter for {{date}}, up to 200 words, in 4 parts: update: {{news}}; useful tip: {{topic}}; behind the scenes: {{context}}; offer or invitation: {{offer}}. Tone: {{tone}}. Give me 3 subject lines (benefit, curiosity, urgency) and a 2-sentence version for WhatsApp. Plain text.", "labels": {"date": ["Month", "e.g. December"], "topic": ["Useful tip", "e.g. how to choose raw honey"], "context": ["Behind the scenes", "e.g. new partnership with a local producer"], "offer": ["Offer or invitation", "e.g. 10% off hampers until the 15th"]}}, "checklist": ["I used the fixed 4-part format", "All facts and prices came from me", "I have 3 subject lines to choose from", "There''s one clear action for the customer", "I made the short WhatsApp or SMS version"], "tips": [{"title": "Same day, same time", "text": "Sending on the same day each month builds the habit, for you and for your customers."}, {"title": "Collect questions", "text": "The questions customers ask at the counter make the best topic for the monthly tip."}]}'::jsonb from public.learn_lessons where slug = 'newsletter-mensal'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('propostas-orcamentos', 'setor', 'freelancers', 121, true, 6, 'intermedio', 'Propostas e orçamentos que fecham', 'Proposals and quotes that close', 'Transforma as notas de uma reunião numa proposta clara, com âmbito, prazos e preço, em 10 minutos.', 'Turn your meeting notes into a clear proposal with scope, timeline and price in 10 minutes.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Depois de uma boa reunião, a proposta demora dias a sair e quando sai é um bloco de texto sobre ti, não sobre o problema do cliente. Âmbito vago gera pedidos extra sem fim e discussões sobre o preço.", "steps": [{"title": "Começa pelo problema do cliente", "text": "Cola as tuas notas da reunião e pede que a proposta abra com o problema e o resultado que o cliente quer, nas palavras dele."}, {"title": "Define o âmbito com limites", "text": "Pede uma lista do que está incluído, do que não está e de quantas revisões existem. É isto que evita pedidos extra."}, {"title": "Preço com opções e próximos passos", "text": "Pede 2 ou 3 opções (essencial, recomendada, completa), prazos por fase e um próximo passo concreto com data."}], "before": {"prompt": "Escreve uma proposta para fazer o site de um cliente.", "note": "Sem problema, sem âmbito, sem preço: a proposta vai ser genérica e aberta a mal-entendidos."}, "after": {"prompt": "Sou designer web freelancer. Notas da reunião: cliente é uma clínica dentária em Leiria; o site atual não aparece no Google e não permite marcações; querem lançar antes de março. Escreve uma proposta com: 1) o problema e o resultado pretendido, em 3 frases; 2) âmbito incluído e não incluído; 3) 2 revisões por fase; 4) três opções de preço: 1200, 1800 e 2500 euros, com o que cada uma inclui; 5) calendário em 3 fases; 6) próximo passo: reunião de 20 minutos até sexta. Tom profissional e direto. Texto simples.", "note": "Foco no cliente, limites claros e uma decisão fácil de tomar."}, "try": {"intro": "Cola as notas da tua reunião e abre no Criar Prompt.", "target": "builder", "template": "Sou {{profissao}} freelancer. Cliente: {{cliente}}. Notas da reunião: {{notas}}. Escreve uma proposta com: o problema e o resultado pretendido em 3 frases; âmbito incluído e não incluído; número de revisões; três opções de preço a partir de {{preco}}; calendário por fases até {{data_fim}}; e um próximo passo concreto. Tom profissional e direto. Texto simples.", "labels": {"notas": ["Notas da reunião", "Cola aqui as tuas notas"], "preco": ["Preço da opção base", "Ex.: 1200 €"], "data_fim": ["Prazo final", "Ex.: fim de fevereiro"]}}, "checklist": ["A proposta abre com o problema do cliente", "Há uma lista do que não está incluído", "Defini o número de revisões", "Há 2 ou 3 opções de preço", "Termina com um próximo passo e data"], "tips": [{"title": "A opção do meio", "text": "Com três opções, a maioria dos clientes escolhe a do meio. Coloca lá o que realmente recomendas."}, {"title": "Reaproveita", "text": "Guarda a estrutura da proposta na Biblioteca. Nas próximas, mudas só as notas e os preços."}]}'::jsonb, '{"problem": "After a good meeting, the proposal takes days, and when it''s sent it''s a wall of text about you rather than the client''s problem. A vague scope leads to endless extra requests and arguments about price.", "steps": [{"title": "Start with the client''s problem", "text": "Paste your meeting notes and ask for the proposal to open with the problem and the result the client wants, in their words."}, {"title": "Define the scope with limits", "text": "Ask for a list of what''s included, what isn''t and how many revision rounds there are. That''s what stops scope creep."}, {"title": "Price options and next steps", "text": "Ask for 2 or 3 options (essential, recommended, complete), a timeline per phase and one concrete next step with a date."}], "before": {"prompt": "Write a proposal for building a client''s website.", "note": "No problem, no scope, no price: the proposal will be generic and open to misunderstandings."}, "after": {"prompt": "I''m a freelance web designer. Meeting notes: the client is a dental clinic in Norwich; their current site doesn''t show up on Google and doesn''t allow online booking; they want to launch before March. Write a proposal with: 1) the problem and desired outcome in 3 sentences; 2) included and excluded scope; 3) 2 revision rounds per phase; 4) three price options: 1,200, 1,800 and 2,500 pounds, with what each includes; 5) a 3-phase timeline; 6) next step: a 20-minute call by Friday. Professional, direct tone. Plain text.", "note": "Client-focused, clear limits and an easy decision to make."}, "try": {"intro": "Paste your meeting notes and open in Create Prompt.", "target": "builder", "template": "I''m a freelance {{profession}}. Client: {{client}}. Meeting notes: {{notes}}. Write a proposal with: the problem and desired outcome in 3 sentences; included and excluded scope; number of revision rounds; three price options starting at {{price}}; a phased timeline ending {{end_date}}; and one concrete next step. Professional, direct tone. Plain text.", "labels": {"notes": ["Meeting notes", "Paste your notes here"], "price": ["Base option price", "e.g. £1,200"], "end_date": ["Final deadline", "e.g. end of February"]}}, "checklist": ["The proposal opens with the client''s problem", "There''s a list of what''s not included", "I set the number of revisions", "There are 2 or 3 price options", "It ends with a next step and a date"], "tips": [{"title": "The middle option", "text": "With three options, most clients pick the middle one. Put what you actually recommend there."}, {"title": "Reuse it", "text": "Save the proposal structure in your Library. Next time, you only change the notes and prices."}]}'::jsonb from public.learn_lessons where slug = 'propostas-orcamentos'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('follow-up-clientes', 'setor', 'freelancers', 122, false, 5, 'intermedio', 'Follow-up de clientes sem parecer insistente', 'Following up with clients without being pushy', 'Uma sequência de 3 mensagens para propostas sem resposta e faturas em atraso, firme mas simpática.', 'A 3-message sequence for unanswered proposals and overdue invoices: firm but friendly.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Enviaste a proposta ou a fatura e o silêncio instala-se. Tens medo de parecer insistente, por isso adias, e o negócio arrefece ou o pagamento atrasa ainda mais. Falta-te uma sequência pronta, com o tom certo para cada momento.", "steps": [{"title": "Define a situação e o histórico", "text": "Diz o que enviaste, quando, e o que sabes do cliente: \"proposta enviada há 8 dias, cliente pareceu interessado, mencionou orçamento apertado\"."}, {"title": "Pede uma sequência com escalada suave", "text": "Mensagem 1: lembrete leve com valor acrescentado. Mensagem 2: pergunta direta com opções. Mensagem 3: encerramento cordial que deixa a porta aberta."}, {"title": "Curto, com uma pergunta fácil", "text": "Cada mensagem até 70 palavras, a terminar com uma pergunta de resposta fácil (\"Faz sentido falarmos na quinta?\")."}], "before": {"prompt": "Escreve um email a perguntar ao cliente se já viu a proposta.", "note": "Uma mensagem isolada, sem plano para os dias seguintes nem valor acrescentado."}, "after": {"prompt": "Sou fotógrafo freelancer. Enviei uma proposta de 900 euros para fotografar o catálogo de uma marca de calçado há 8 dias, sem resposta. Na reunião disseram que o orçamento estava apertado. Escreve 3 emails de follow-up (dia 8, dia 14, dia 21), até 70 palavras cada: 1) lembrete leve com uma ideia útil para o catálogo; 2) pergunta direta e uma opção mais simples por 600 euros; 3) encerramento cordial a deixar a porta aberta. Cada um termina com uma pergunta fácil. Texto simples.", "note": "Sequência completa, tom progressivo e uma saída para o orçamento do cliente."}, "try": {"intro": "Preenche a tua situação e abre no Criar Prompt.", "target": "builder", "template": "Sou {{profissao}} freelancer. Situação: {{situacao}}, enviada há {{numero}} dias, sem resposta. O que sei do cliente: {{notas}}. Escreve 3 mensagens de follow-up (dia 8, 14 e 21), até 70 palavras cada: lembrete leve com valor acrescentado; pergunta direta com uma alternativa ({{opcao_b}}); encerramento cordial. Cada uma termina com uma pergunta fácil. Texto simples.", "labels": {"situacao": ["O que enviaste", "Ex.: proposta de 900 € para um catálogo"], "numero": ["Dias sem resposta", "Ex.: 8"], "notas": ["O que sabes do cliente", "Ex.: disse que o orçamento estava apertado"], "opcao_b": ["Alternativa a oferecer", "Ex.: versão mais simples por 600 €"]}}, "checklist": ["Dei o histórico e o que sei do cliente", "A sequência tem 3 passos com datas", "A primeira mensagem acrescenta valor", "Há uma alternativa para o cliente", "Cada mensagem acaba numa pergunta fácil"], "tips": [{"title": "Faturas em atraso", "text": "Para faturas, mantém o mesmo método: lembrete com o número da fatura e o IBAN, depois pergunta direta, depois prazo final. Sem pedir desculpa por cobrar."}, {"title": "Agenda os envios", "text": "Agenda as 3 mensagens no teu email no dia em que envias a proposta. Se o cliente responder, cancelas."}]}'::jsonb, '{"problem": "You sent the proposal or invoice and then: silence. You don''t want to seem pushy, so you put it off, and the deal goes cold or the payment slips further. What''s missing is a ready sequence with the right tone for each stage.", "steps": [{"title": "Describe the situation and history", "text": "Say what you sent, when, and what you know about the client: \"proposal sent 8 days ago, client seemed keen, mentioned a tight budget\"."}, {"title": "Ask for a gently escalating sequence", "text": "Message 1: a light reminder that adds value. Message 2: a direct question with options. Message 3: a courteous close that leaves the door open."}, {"title": "Short, with an easy question", "text": "Each message under 70 words, ending with an easy-to-answer question (\"Shall we talk on Thursday?\")."}], "before": {"prompt": "Write an email asking the client whether they''ve seen the proposal.", "note": "One isolated message, no plan for the following days and no added value."}, "after": {"prompt": "I''m a freelance photographer. I sent a 900-pound proposal to shoot a footwear brand''s catalogue 8 days ago, no reply. In the meeting they said budget was tight. Write 3 follow-up emails (day 8, day 14, day 21), under 70 words each: 1) a light reminder with a useful idea for the catalogue; 2) a direct question and a simpler option for 600 pounds; 3) a courteous close leaving the door open. Each ends with an easy question. Plain text.", "note": "A complete sequence, a progressive tone and a way out for the client''s budget."}, "try": {"intro": "Describe your situation and open in Create Prompt.", "target": "builder", "template": "I''m a freelance {{profession}}. Situation: {{situation}}, sent {{number}} days ago, no reply. What I know about the client: {{notes}}. Write 3 follow-up messages (day 8, 14 and 21), under 70 words each: a light reminder that adds value; a direct question with an alternative ({{option_b}}); a courteous close. Each ends with an easy question. Plain text.", "labels": {"situation": ["What you sent", "e.g. a 900-pound catalogue proposal"], "number": ["Days without reply", "e.g. 8"], "notes": ["What you know about the client", "e.g. said the budget was tight"], "option_b": ["Alternative to offer", "e.g. a simpler version for 600 pounds"]}}, "checklist": ["I gave the history and what I know about the client", "The sequence has 3 dated steps", "The first message adds value", "There''s an alternative for the client", "Each message ends with an easy question"], "tips": [{"title": "Overdue invoices", "text": "For invoices, use the same method: a reminder with the invoice number and bank details, then a direct question, then a final deadline. Never apologise for asking to be paid."}, {"title": "Schedule the sends", "text": "Schedule all 3 messages in your email on the day you send the proposal. If the client replies, cancel them."}]}'::jsonb from public.learn_lessons where slug = 'follow-up-clientes'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('anuncio-imovel', 'setor', 'imobiliario', 131, true, 5, 'basico', 'Anúncio de imóvel para portais', 'Property listings for portals', 'Da ficha técnica a um anúncio que vende o estilo de vida, sem exageros nem dados errados.', 'From the spec sheet to a listing that sells the lifestyle, with no hype and no wrong details.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Os anúncios nos portais parecem todos iguais: \"Excelente T2, ótima localização, muita luz\". O comprador passa à frente. E quando a IA escreve sem dados, inventa metros quadrados, certificados energéticos ou vistas que não existem, o que é um risco sério.", "steps": [{"title": "Dá a ficha técnica completa", "text": "Tipologia, área útil, andar, elevador, estacionamento, certificado energético, ano, preço e 3 pontos fortes reais. A IA só escreve sobre o que lhe dás."}, {"title": "Descreve o comprador ideal", "text": "\"Casal jovem que trabalha em Lisboa e quer espaço para um filho\" muda o texto: realça o quarto extra, as escolas e os transportes."}, {"title": "Estrutura para o portal", "text": "Título até 60 caracteres, uma abertura sobre o dia a dia no imóvel, descrição por divisões, zona e acessos, e um apelo para marcar visita. Proíbe superlativos vazios."}], "before": {"prompt": "Escreve um anúncio para um T2 em Almada.", "note": "Sem dados: a IA vai preencher com clichés ou, pior, inventar características."}, "after": {"prompt": "Ficha: T2 em Almada (Cova da Piedade), 85 m2 úteis, 3.º andar com elevador, lugar de garagem, certificado energético C, construção de 2004, 265 000 euros. Pontos fortes: varanda virada a sul, cozinha remodelada em 2022, 5 minutos a pé do metro de superfície. Comprador ideal: casal jovem que trabalha em Lisboa. Escreve: título até 60 caracteres; abertura de 2 frases sobre o dia a dia; descrição por divisões; zona e acessos; apelo a marcar visita. Sem superlativos vazios nem dados que não estejam na ficha. Texto simples.", "note": "Dados reais, comprador definido e estrutura própria para portal."}, "try": {"intro": "Preenche a ficha do imóvel e abre no Criar Prompt.", "target": "builder", "template": "Ficha do imóvel: {{tipologia}} em {{zona}}, {{area}} m2, preço {{preco}}. Pontos fortes: {{notas}}. Comprador ideal: {{cliente_ideal}}. Escreve para {{plataforma}}: título até 60 caracteres; abertura de 2 frases sobre o dia a dia; descrição por divisões; zona e acessos; apelo a marcar visita. Sem superlativos vazios nem dados fora da ficha. Texto simples.", "labels": {"notas": ["Pontos fortes reais", "Ex.: varanda a sul, cozinha remodelada"], "cliente_ideal": ["Comprador ideal", "Ex.: casal jovem que trabalha em Lisboa"], "plataforma": ["Portal", "Ex.: Idealista"]}}, "checklist": ["A ficha técnica está completa e confirmada", "Defini o comprador ideal", "O título tem até 60 caracteres", "Não há dados inventados nem superlativos vazios", "Termina com um apelo a marcar visita"], "tips": [{"title": "Uma versão por portal", "text": "Pede também uma versão curta para redes sociais e outra em inglês para compradores estrangeiros."}, {"title": "Fotos na ordem do texto", "text": "Ordena as fotografias pela mesma sequência da descrição. O anúncio fica mais coerente."}]}'::jsonb, '{"problem": "Portal listings all look alike: \"Superb 2-bed, great location, lots of light\". Buyers scroll past. And when AI writes without data, it invents square metres, energy ratings or views that don''t exist, which is a serious risk.", "steps": [{"title": "Provide the full spec sheet", "text": "Bedrooms, floor area, floor level, lift, parking, energy rating, year built, price and 3 real selling points. The AI only writes about what you give it."}, {"title": "Describe the ideal buyer", "text": "\"Young couple commuting to London who want room for a child\" changes the copy: it highlights the spare room, schools and transport links."}, {"title": "Structure it for the portal", "text": "A headline under 60 characters, an opening about daily life in the home, a room-by-room description, area and transport, and a call to book a viewing. Ban empty superlatives."}], "before": {"prompt": "Write a listing for a 2-bed flat in Croydon.", "note": "No data: the AI will fill it with clichés or, worse, invent features."}, "after": {"prompt": "Spec: 2-bed flat in Croydon (East Croydon), 70 m2, 3rd floor with lift, one parking space, EPC rating C, built 2004, 320,000 pounds. Selling points: south-facing balcony, kitchen refitted in 2022, 5-minute walk to the station. Ideal buyer: young couple commuting to London. Write: a headline under 60 characters; a 2-sentence opening about daily life; a room-by-room description; area and transport; a call to book a viewing. No empty superlatives and no details that aren''t in the spec. Plain text.", "note": "Real data, a defined buyer and a portal-ready structure."}, "try": {"intro": "Fill in the property spec and open in Create Prompt.", "target": "builder", "template": "Property spec: {{property_type}} in {{location}}, {{size}} m2, price {{price}}. Selling points: {{notes}}. Ideal buyer: {{ideal_client}}. Write for {{platform}}: a headline under 60 characters; a 2-sentence opening about daily life; a room-by-room description; area and transport; a call to book a viewing. No empty superlatives and nothing outside the spec. Plain text.", "labels": {"notes": ["Real selling points", "e.g. south-facing balcony, new kitchen"], "ideal_client": ["Ideal buyer", "e.g. young couple commuting to London"], "platform": ["Portal", "e.g. Rightmove"], "location": ["Area", "e.g. East Croydon"]}}, "checklist": ["The spec sheet is complete and confirmed", "I defined the ideal buyer", "The headline is under 60 characters", "No invented details or empty superlatives", "It ends with a call to book a viewing"], "tips": [{"title": "One version per channel", "text": "Also ask for a short social media version and one in another language for international buyers."}, {"title": "Photos in text order", "text": "Order the photos in the same sequence as the description. The listing feels more coherent."}]}'::jsonb from public.learn_lessons where slug = 'anuncio-imovel'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('leads-imobiliario', 'setor', 'imobiliario', 132, false, 6, 'intermedio', 'Responder e qualificar leads', 'Replying to and qualifying leads', 'Respostas rápidas a pedidos de informação que qualificam o interessado e marcam a visita.', 'Fast replies to enquiries that qualify the prospect and book the viewing.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Chegam dezenas de contactos dos portais e muitos nunca se tornam visitas. Responder tarde ou com uma mensagem genérica faz perder o comprador para outro consultor. E sem qualificar, gastas tempo em visitas a quem ainda não pode comprar.", "steps": [{"title": "Responde em minutos, com o essencial", "text": "Agradece, confirma que o imóvel está disponível e dá 1 ou 2 informações úteis que o anúncio não tem (custos de condomínio, data de disponibilidade)."}, {"title": "Qualifica com 3 perguntas", "text": "Pede à IA 3 perguntas simpáticas e diretas: prazo para comprar, financiamento (pré-aprovação ou capital próprio) e o que é indispensável para a pessoa."}, {"title": "Propõe 2 horários concretos", "text": "Termina sempre com duas opções de visita em vez de \"diga-me quando pode\". Facilita o sim."}], "before": {"prompt": "Responde a este contacto: \"Olá, o T3 ainda está disponível?\"", "note": "Sem informação extra, sem qualificação e sem proposta de visita."}, "after": {"prompt": "Sou consultor imobiliário em Braga. Pedido via portal: \"Olá, o T3 da Rua do Souto ainda está disponível?\" Dados: disponível, condomínio 35 euros por mês, livre para escritura em fevereiro. Escreve uma resposta para WhatsApp até 90 palavras: agradece, confirma a disponibilidade, acrescenta os 2 dados, faz 3 perguntas de qualificação (prazo, financiamento, indispensáveis) e propõe visita na quinta às 18h30 ou no sábado às 11h. Tom próximo e profissional. Texto simples.", "note": "Resposta útil, qualificação natural e um passo seguinte concreto."}, "try": {"intro": "Cola um pedido real (sem dados pessoais) e abre no Criar Prompt.", "target": "builder", "template": "Sou consultor imobiliário em {{localidade}}. Pedido recebido: {{mensagem}}. Dados do imóvel: {{notas}}. Escreve uma resposta para {{plataforma}} até 90 palavras: agradece, confirma a disponibilidade, acrescenta 2 dados úteis, faz 3 perguntas de qualificação (prazo, financiamento, indispensáveis) e propõe visita em {{horario}}. Tom próximo e profissional. Texto simples.", "labels": {"mensagem": ["Pedido recebido", "Cola aqui a mensagem (sem dados pessoais)"], "notas": ["Dados do imóvel", "Ex.: condomínio 35 €/mês, livre em fevereiro"], "plataforma": ["Canal", "Ex.: WhatsApp"], "horario": ["Dois horários de visita", "Ex.: quinta 18h30 ou sábado 11h"]}}, "checklist": ["Respondi com dados que o anúncio não tinha", "Fiz 3 perguntas de qualificação", "Propus 2 horários concretos", "A mensagem cabe num ecrã de telemóvel", "Não incluí dados pessoais no prompt"], "tips": [{"title": "Modelos por fase", "text": "Cria modelos para cada fase: primeiro contacto, pós-visita, proposta e pós-escritura. Guarda-os na Biblioteca."}, {"title": "Pós-visita em 24 horas", "text": "Pede à IA uma mensagem pós-visita que resuma os 3 pontos de que a pessoa mais gostou e pergunte o próximo passo."}]}'::jsonb, '{"problem": "Dozens of portal enquiries come in and many never turn into viewings. A slow or generic reply loses the buyer to another agent. And without qualifying, you waste time showing homes to people who can''t buy yet.", "steps": [{"title": "Reply within minutes, with the essentials", "text": "Thank them, confirm the property is available and give 1 or 2 useful details the listing doesn''t include (service charge, availability date)."}, {"title": "Qualify with 3 questions", "text": "Ask the AI for 3 friendly, direct questions: timeline to buy, financing (mortgage in principle or cash) and their must-haves."}, {"title": "Offer 2 specific slots", "text": "Always end with two viewing options instead of \"let me know when suits you\". It makes yes easy."}], "before": {"prompt": "Reply to this enquiry: \"Hi, is the 3-bed still available?\"", "note": "No extra information, no qualifying and no viewing offer."}, "after": {"prompt": "I''m an estate agent in Bristol. Portal enquiry: \"Hi, is the 3-bed on Park Street still available?\" Details: available, service charge 90 pounds a month, chain-free, completion possible in February. Write a WhatsApp reply under 90 words: thank them, confirm availability, add the 2 details, ask 3 qualifying questions (timeline, financing, must-haves) and offer a viewing on Thursday at 6.30pm or Saturday at 11am. Friendly, professional tone. Plain text.", "note": "A useful reply, natural qualifying and a concrete next step."}, "try": {"intro": "Paste a real enquiry (without personal data) and open in Create Prompt.", "target": "builder", "template": "I''m an estate agent in {{location}}. Enquiry received: {{message}}. Property details: {{notes}}. Write a reply for {{platform}} under 90 words: thank them, confirm availability, add 2 useful details, ask 3 qualifying questions (timeline, financing, must-haves) and offer a viewing at {{hours}}. Friendly, professional tone. Plain text.", "labels": {"message": ["Enquiry received", "Paste the message (no personal data)"], "notes": ["Property details", "e.g. service charge £90/month, chain-free"], "platform": ["Channel", "e.g. WhatsApp"], "hours": ["Two viewing slots", "e.g. Thu 6.30pm or Sat 11am"]}}, "checklist": ["I replied with details the listing didn''t have", "I asked 3 qualifying questions", "I offered 2 specific slots", "The message fits on a phone screen", "I left personal data out of the prompt"], "tips": [{"title": "Templates per stage", "text": "Create templates for each stage: first contact, after the viewing, offer and after completion. Save them in your Library."}, {"title": "Follow up within 24 hours", "text": "Ask the AI for a post-viewing message that recaps the 3 things the person liked most and asks about the next step."}]}'::jsonb from public.learn_lessons where slug = 'leads-imobiliario'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('anuncio-alojamento', 'setor', 'hotelaria', 141, true, 5, 'basico', 'Anúncio de alojamento no Airbnb e Booking', 'Airbnb and Booking listings', 'Um título e uma descrição que destacam o que o teu hóspede ideal procura, dentro dos limites de cada plataforma.', 'A title and description that highlight what your ideal guest is looking for, within each platform''s limits.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "O anúncio é a montra do alojamento, mas muitos repetem \"acolhedor e bem localizado\". O hóspede compara dezenas de opções no telemóvel e decide pelo título, pela primeira frase e pelas comodidades. Se não falas com quem queres atrair, perdes reservas.", "steps": [{"title": "Escolhe o hóspede ideal", "text": "Famílias, casais, nómadas digitais ou surfistas procuram coisas diferentes. Escolhe um principal e diz o que é importante para ele (berço, secretária, guardar pranchas)."}, {"title": "Lista factos e comodidades", "text": "Capacidade, quartos, distâncias a pé, estacionamento, Wi-Fi com velocidade, check-in autónomo. Factos concretos convencem mais do que adjetivos."}, {"title": "Respeita os limites da plataforma", "text": "Título até 50 caracteres, resumo até 500, depois espaço, zona e acessos. Pede também as 10 comodidades a destacar."}], "before": {"prompt": "Escreve a descrição do meu apartamento para o Airbnb.", "note": "Sem hóspede, sem factos, sem limites: o texto sai genérico."}, "after": {"prompt": "Apartamento T1 na Ericeira, até 3 pessoas, a 400 metros da praia de Ribeira d''Ilhas. Hóspede ideal: surfistas e casais que trabalham à distância. Factos: Wi-Fi de fibra 500 Mb, secretária, chuveiro exterior, espaço para guardar pranchas, estacionamento gratuito na rua, check-in autónomo. Escreve: título até 50 caracteres; resumo até 500 caracteres; descrição do espaço; zona e acessos; e as 10 comodidades a destacar. Sem dados inventados. Texto simples.", "note": "Hóspede definido, factos concretos e estrutura dentro dos limites."}, "try": {"intro": "Preenche e abre no Criar Prompt. Depois adapta o resumo ao Booking.", "target": "builder", "template": "Alojamento: {{tipologia}} em {{localidade}}. Hóspede ideal: {{tipo_hospede}}. Factos e comodidades: {{notas}}. Escreve para {{plataforma}}: título até 50 caracteres; resumo até 500 caracteres; descrição do espaço; zona e acessos; as 10 comodidades a destacar. Sem dados inventados. Texto simples.", "labels": {"notas": ["Factos e comodidades", "Ex.: Wi-Fi 500 Mb, secretária, estacionamento grátis"], "plataforma": ["Plataforma", "Ex.: Airbnb"], "tipologia": ["Tipo de alojamento", "Ex.: apartamento T1"]}}, "checklist": ["Escolhi um hóspede ideal", "Usei distâncias e números reais", "O título tem até 50 caracteres", "O resumo tem até 500 caracteres", "Pedi as 10 comodidades a destacar"], "tips": [{"title": "Versão noutras línguas", "text": "Pede a mesma descrição em inglês, francês e espanhol, adaptada, não traduzida à letra."}, {"title": "Responde ao que perguntam", "text": "As perguntas que os hóspedes fazem antes de reservar indicam o que falta no anúncio. Acrescenta essas respostas."}]}'::jsonb, '{"problem": "Your listing is your shop window, yet many say \"cosy and well located\". Guests compare dozens of options on their phone and decide on the title, the first line and the amenities. If you don''t speak to the guest you want, you lose bookings.", "steps": [{"title": "Choose the ideal guest", "text": "Families, couples, digital nomads or surfers look for different things. Pick one main guest and say what matters to them (cot, desk, board storage)."}, {"title": "List facts and amenities", "text": "Capacity, bedrooms, walking distances, parking, Wi-Fi with speed, self check-in. Concrete facts persuade more than adjectives."}, {"title": "Respect the platform limits", "text": "Title up to 50 characters, summary up to 500, then the space, the area and getting around. Also ask for the 10 amenities to highlight."}], "before": {"prompt": "Write the description of my flat for Airbnb.", "note": "No guest, no facts, no limits: the copy comes out generic."}, "after": {"prompt": "One-bedroom flat in Newquay, sleeps 3, 400 metres from Fistral Beach. Ideal guest: surfers and couples who work remotely. Facts: 500 Mb fibre Wi-Fi, desk, outdoor shower, board storage, free street parking, self check-in. Write: a title up to 50 characters; a summary up to 500 characters; a description of the space; the area and getting around; and the 10 amenities to highlight. No invented details. Plain text.", "note": "A defined guest, concrete facts and a structure within the limits."}, "try": {"intro": "Fill in the fields and open in Create Prompt. Then adapt the summary for Booking.", "target": "builder", "template": "Property: {{property_type}} in {{location}}. Ideal guest: {{guest_type}}. Facts and amenities: {{notes}}. Write for {{platform}}: a title up to 50 characters; a summary up to 500 characters; a description of the space; the area and getting around; the 10 amenities to highlight. No invented details. Plain text.", "labels": {"notes": ["Facts and amenities", "e.g. 500 Mb Wi-Fi, desk, free parking"], "platform": ["Platform", "e.g. Airbnb"], "property_type": ["Property type", "e.g. one-bedroom flat"]}}, "checklist": ["I chose an ideal guest", "I used real distances and numbers", "The title is under 50 characters", "The summary is under 500 characters", "I asked for the 10 amenities to highlight"], "tips": [{"title": "Other languages", "text": "Ask for the same description in French, German and Spanish, adapted rather than translated word for word."}, {"title": "Answer what guests ask", "text": "Questions guests ask before booking show what''s missing from your listing. Add those answers."}]}'::jsonb from public.learn_lessons where slug = 'anuncio-alojamento'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('mensagens-hospedes', 'setor', 'hotelaria', 142, false, 5, 'intermedio', 'Mensagens automáticas para hóspedes', 'Automated guest messages', 'Um conjunto de 5 mensagens, da reserva ao pedido de avaliação, que poupa perguntas e melhora as avaliações.', 'A set of 5 messages, from booking to review request, that saves questions and improves your reviews.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Os hóspedes fazem sempre as mesmas perguntas: como chegar, onde estacionar, a palavra-passe do Wi-Fi, a hora do check-out. Responder uma a uma gasta horas, e esquecer o pedido de avaliação custa estrelas e visibilidade.", "steps": [{"title": "Mapeia os 5 momentos", "text": "Confirmação da reserva, 3 dias antes, dia do check-in, a meio da estadia e após o check-out. Cada momento tem um objetivo diferente."}, {"title": "Dá as informações práticas", "text": "Morada, estacionamento, código da porta (com a instrução de o enviar só no dia), Wi-Fi, regras da casa e 3 recomendações locais tuas."}, {"title": "Curto e com um objetivo por mensagem", "text": "Até 80 palavras cada, com o nome do hóspede em variável. A mensagem do check-out agradece e pede a avaliação de forma simples."}], "before": {"prompt": "Escreve uma mensagem de boas-vindas para os hóspedes.", "note": "Uma mensagem isolada: as perguntas continuam a chegar ao longo da estadia."}, "after": {"prompt": "Alojamento local em Évora, casa para 4 pessoas no centro histórico. Escreve 5 mensagens até 80 palavras cada, com [NOME] no lugar do nome do hóspede: 1) confirmação da reserva; 2) 3 dias antes, com como chegar e onde estacionar (parque do Rossio, 5 minutos a pé); 3) dia do check-in, com o código [CÓDIGO] e o Wi-Fi [WIFI]; 4) a meio da estadia, a perguntar se precisa de algo e a sugerir 3 restaurantes (Fialho, Botequim da Mouraria, Dom Joaquim); 5) após o check-out, a agradecer e a pedir a avaliação. Tom caloroso. Texto simples.", "note": "O percurso completo do hóspede, informação prática e o pedido de avaliação no momento certo."}, "try": {"intro": "Preenche os teus dados e abre no Criar Prompt. Depois copia cada mensagem para as respostas automáticas da plataforma.", "target": "builder", "template": "Alojamento: {{tipologia}} em {{localidade}}. Escreve 5 mensagens até 80 palavras, com [NOME] no lugar do nome do hóspede: confirmação da reserva; 3 dias antes, com chegada e estacionamento ({{notas}}); dia do check-in, com o código e o Wi-Fi como [CÓDIGO] e [WIFI]; a meio da estadia, com 3 recomendações ({{referencia}}); após o check-out, a agradecer e a pedir avaliação. Tom {{tom}}. Texto simples.", "labels": {"notas": ["Chegada e estacionamento", "Ex.: parque do Rossio, 5 minutos a pé"], "referencia": ["As tuas 3 recomendações", "Ex.: Fialho, Botequim da Mouraria, Dom Joaquim"], "tipologia": ["Tipo de alojamento", "Ex.: casa para 4 pessoas"]}}, "checklist": ["Cobri os 5 momentos da estadia", "Os dados sensíveis ficam como [CÓDIGO] e [WIFI] no prompt", "Cada mensagem tem um só objetivo", "Incluí recomendações locais reais", "A última mensagem pede a avaliação"], "tips": [{"title": "Programa na plataforma", "text": "Airbnb e Booking permitem agendar mensagens. Configura uma vez e esquece."}, {"title": "Versão em inglês", "text": "Pede as 5 mensagens também em inglês. A maioria dos hóspedes estrangeiros agradece."}]}'::jsonb, '{"problem": "Guests always ask the same things: how to get there, where to park, the Wi-Fi password, check-out time. Answering one by one takes hours, and forgetting to ask for a review costs you stars and visibility.", "steps": [{"title": "Map the 5 moments", "text": "Booking confirmation, 3 days before, check-in day, mid-stay and after check-out. Each moment has a different goal."}, {"title": "Provide the practical info", "text": "Address, parking, door code (with an instruction to send it only on the day), Wi-Fi, house rules and 3 of your own local recommendations."}, {"title": "Short, with one goal per message", "text": "Up to 80 words each, with the guest''s name as a variable. The check-out message thanks them and asks for a review simply."}], "before": {"prompt": "Write a welcome message for guests.", "note": "One isolated message: the questions keep coming throughout the stay."}, "after": {"prompt": "Holiday let in York, a house for 4 in the old town. Write 5 messages of up to 80 words each, with [NAME] in place of the guest''s name: 1) booking confirmation; 2) 3 days before, with directions and parking (Marygate car park, 5 minutes'' walk); 3) check-in day, with the code [CODE] and Wi-Fi [WIFI]; 4) mid-stay, asking if they need anything and suggesting 3 restaurants; 5) after check-out, thanking them and asking for a review. Warm tone. Plain text.", "note": "The whole guest journey, practical info and the review request at the right moment."}, "try": {"intro": "Fill in your details and open in Create Prompt. Then paste each message into the platform''s scheduled replies.", "target": "builder", "template": "Property: {{property_type}} in {{location}}. Write 5 messages of up to 80 words, with [NAME] in place of the guest''s name: booking confirmation; 3 days before, with arrival and parking ({{notes}}); check-in day, with the code and Wi-Fi as [CODE] and [WIFI]; mid-stay, with 3 recommendations ({{reference}}); after check-out, thanking them and asking for a review. Tone: {{tone}}. Plain text.", "labels": {"notes": ["Arrival and parking", "e.g. Marygate car park, 5 minutes'' walk"], "reference": ["Your 3 recommendations", "e.g. three local restaurants"], "property_type": ["Property type", "e.g. house for 4"]}}, "checklist": ["I covered all 5 moments of the stay", "Sensitive details stay as [CODE] and [WIFI] in the prompt", "Each message has a single goal", "I included real local recommendations", "The last message asks for a review"], "tips": [{"title": "Schedule it on the platform", "text": "Airbnb and Booking let you schedule messages. Set it up once and forget it."}, {"title": "Other languages", "text": "Ask for the 5 messages in other languages too. International guests appreciate it."}]}'::jsonb from public.learn_lessons where slug = 'mensagens-hospedes'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('exemplos-no-prompt', 'avancado', null, 201, false, 6, 'avancado', 'Exemplos no prompt (few-shot)', 'Examples in the prompt (few-shot)', 'Mostra 2 ou 3 exemplos do que queres e a IA copia o estilo, o tamanho e a estrutura com muito mais precisão.', 'Show 2 or 3 examples of what you want and the AI matches the style, length and structure far more precisely.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Há coisas difíceis de descrever: o teu tom, o ritmo das tuas legendas, o formato exato de uma ficha de produto. Podes gastar parágrafos a explicar, ou mostrar. Sem exemplos, a IA aproxima-se; com exemplos, acerta.", "steps": [{"title": "Escolhe 2 ou 3 exemplos reais", "text": "Usa textos teus que funcionaram: as melhores legendas, descrições ou respostas. Devem ser variados no tema mas iguais no estilo."}, {"title": "Separa exemplos e tarefa", "text": "Marca claramente: \"Exemplo 1:\", \"Exemplo 2:\" e depois \"Agora escreve para:\". Diz o que deve imitar (tom, tamanho, estrutura) e o que não deve copiar (frases inteiras)."}, {"title": "Pede uma explicação do padrão", "text": "Pede à IA que descreva em 3 linhas o padrão que identificou antes de escrever. Se o padrão estiver errado, corriges antes do resultado."}], "before": {"prompt": "Escreve descrições de produto no estilo da minha loja.", "note": "A IA não conhece o estilo da tua loja e vai adivinhar."}, "after": {"prompt": "Exemplo 1: \"Caneca Mar. Grés pintado à mão nas Caldas. 350 ml. Para cafés longos e manhãs lentas.\" Exemplo 2: \"Taça Serra. Barro preto de Bisalhães. 15 cm. Para sopas que aquecem a alma.\" Primeiro descreve em 3 linhas o padrão destes exemplos. Depois escreve no mesmo padrão, sem copiar frases, para: prato raso de faiança azul de Coimbra, 27 cm. E para: jarra de vidro soprado da Marinha Grande, 1 litro. Texto simples.", "note": "Dois exemplos definem tom, tamanho e estrutura melhor do que qualquer descrição."}, "try": {"intro": "Cola 2 exemplos teus e abre no Otimizador para ver como o prompt pontua.", "target": "optimizer", "template": "Exemplo 1: {{referencia}}. Exemplo 2: {{rascunho}}. Primeiro descreve em 3 linhas o padrão destes exemplos (tom, tamanho, estrutura). Depois escreve no mesmo padrão, sem copiar frases, para: {{produto}}. Texto simples.", "labels": {"referencia": ["Exemplo 1", "Cola aqui um texto teu que funcionou"], "rascunho": ["Exemplo 2", "Cola aqui outro texto teu"], "produto": ["Para o que queres escrever", "Ex.: prato de faiança azul, 27 cm"]}}, "checklist": ["Usei 2 ou 3 exemplos reais e variados", "Separei bem exemplos e tarefa", "Disse o que imitar e o que não copiar", "Pedi a descrição do padrão primeiro", "Verifiquei que o resultado não repete frases dos exemplos"], "tips": [{"title": "Exemplos negativos", "text": "Também podes mostrar um exemplo do que não queres: \"Evita isto: ...\". Ajuda a afastar clichés."}, {"title": "Guarda o conjunto", "text": "Guarda os exemplos e o prompt na Biblioteca como modelo da tua marca."}]}'::jsonb, '{"problem": "Some things are hard to describe: your tone, the rhythm of your captions, the exact format of a product card. You can spend paragraphs explaining, or you can show. Without examples the AI gets close; with examples it nails it.", "steps": [{"title": "Pick 2 or 3 real examples", "text": "Use your own texts that worked: your best captions, descriptions or replies. They should vary in topic but match in style."}, {"title": "Separate examples from the task", "text": "Label them clearly: \"Example 1:\", \"Example 2:\" and then \"Now write for:\". Say what to imitate (tone, length, structure) and what not to copy (whole sentences)."}, {"title": "Ask it to explain the pattern", "text": "Ask the AI to describe the pattern it found in 3 lines before writing. If the pattern is wrong, you fix it before the output."}], "before": {"prompt": "Write product descriptions in my shop''s style.", "note": "The AI doesn''t know your shop''s style and will guess."}, "after": {"prompt": "Example 1: \"Sea Mug. Hand-painted stoneware from Cornwall. 350 ml. For long coffees and slow mornings.\" Example 2: \"Moor Bowl. Black clay from Devon. 15 cm. For soups that warm the soul.\" First describe the pattern in these examples in 3 lines. Then write in the same pattern, without copying sentences, for: blue earthenware dinner plate from Stoke, 27 cm. And for: hand-blown glass jug from Edinburgh, 1 litre. Plain text.", "note": "Two examples define tone, length and structure better than any description."}, "try": {"intro": "Paste 2 of your own examples and open in the Optimizer to see how the prompt scores.", "target": "optimizer", "template": "Example 1: {{reference}}. Example 2: {{draft}}. First describe in 3 lines the pattern in these examples (tone, length, structure). Then write in the same pattern, without copying sentences, for: {{product}}. Plain text.", "labels": {"reference": ["Example 1", "Paste one of your texts that worked"], "draft": ["Example 2", "Paste another of your texts"], "product": ["What to write for", "e.g. blue earthenware plate, 27 cm"]}}, "checklist": ["I used 2 or 3 real, varied examples", "I clearly separated examples and task", "I said what to imitate and what not to copy", "I asked for the pattern first", "I checked the output doesn''t repeat sentences from the examples"], "tips": [{"title": "Negative examples", "text": "You can also show what you don''t want: \"Avoid this: ...\". It helps steer away from clichés."}, {"title": "Save the set", "text": "Save the examples and the prompt in your Library as your brand template."}]}'::jsonb from public.learn_lessons where slug = 'exemplos-no-prompt'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('criar-template', 'avancado', null, 202, false, 6, 'avancado', 'Criar o teu próprio template com variáveis', 'Build your own template with variables', 'Transforma um prompt que funciona num template reutilizável com campos para preencher, como os dos Packs.', 'Turn a prompt that works into a reusable template with fields to fill in, like the ones in the Packs.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Tens um prompt excelente para responder a avaliações ou fazer propostas, mas cada vez que o usas tens de o procurar, copiar e editar à mão, e acabas por estragar partes que funcionavam. Um template com variáveis resolve isto: mudas só os campos.", "steps": [{"title": "Parte de um prompt testado", "text": "Escolhe um prompt que já deu bons resultados várias vezes. Não faças templates de prompts que ainda estás a afinar."}, {"title": "Marca o que muda com {{chavetas}}", "text": "Troca as partes que mudam por variáveis com nomes claros: {{negocio}}, {{publico}}, {{oferta}}. Tudo o resto (estrutura, limites, tom) fica fixo."}, {"title": "Guarda e reutiliza", "text": "Guarda na Biblioteca com um título que diga para que serve. Ao usá-lo, preenches os campos e o texto fica pronto. Se um campo ficar vazio, aparece em [MAIÚSCULAS] para não te esqueceres."}], "before": {"prompt": "Responde a esta avaliação do restaurante Tasca do Zé, que é de 3 estrelas e fala da sobremesa...", "note": "Um prompt bom mas preso a um caso. Da próxima vez tens de o reescrever."}, "after": {"prompt": "Sou {{funcao}} de {{negocio}}. Avaliação de {{numero}} estrelas: {{avaliacao}}. Escreve uma resposta até 80 palavras: agradece, refere um detalhe concreto, explica sem desculpas genéricas e convida a voltar. Assina como {{nome}}. Texto simples.", "note": "A estrutura vencedora fica fixa; só as variáveis mudam. Reutilizável em segundos."}, "try": {"intro": "Experimenta o formulário com este template. Depois cria o teu e guarda-o na Biblioteca.", "target": "optimizer", "template": "Sou {{funcao}} de {{negocio}}. Tarefa: {{tarefa}}. Público: {{publico}}. Restrições: até {{numero}} palavras, tom {{tom}}, sem jargão. Entrega em texto simples.", "labels": {"numero": ["Máximo de palavras", "Ex.: 120"]}}, "checklist": ["Parti de um prompt já testado", "As variáveis têm nomes claros", "A estrutura e os limites ficaram fixos", "Guardei com um título que diz para que serve", "Testei o template com 2 casos diferentes"], "tips": [{"title": "Poucos campos", "text": "Entre 3 e 6 variáveis é o ideal. Com mais do que isso, o template fica difícil de preencher."}, {"title": "Nomes em minúsculas e sem espaços", "text": "Usa nomes como {{tipo_cliente}}. São mais fáceis de ler e funcionam sempre."}]}'::jsonb, '{"problem": "You have a great prompt for replying to reviews or writing proposals, but each time you use it you have to find it, copy it and edit it by hand, and you end up breaking parts that worked. A template with variables fixes this: you only change the fields.", "steps": [{"title": "Start from a tested prompt", "text": "Pick a prompt that has given good results several times. Don''t template prompts you''re still tweaking."}, {"title": "Mark what changes with {{braces}}", "text": "Replace the parts that change with clearly named variables: {{business}}, {{audience}}, {{offer}}. Everything else (structure, limits, tone) stays fixed."}, {"title": "Save and reuse", "text": "Save it in your Library with a title that says what it''s for. When you use it, fill in the fields and the text is ready. Any empty field shows up in [CAPITALS] so you don''t forget it."}], "before": {"prompt": "Reply to this 3-star review of The Old Kitchen restaurant that mentions the dessert...", "note": "A good prompt, but stuck to one case. Next time you''ll have to rewrite it."}, "after": {"prompt": "I am the {{role}} at {{business}}. {{number}}-star review: {{review}}. Write a reply of up to 80 words: thank them, mention a concrete detail, explain without generic apologies and invite them back. Sign off as {{name}}. Plain text.", "note": "The winning structure stays fixed; only the variables change. Reusable in seconds."}, "try": {"intro": "Try the form with this template. Then build your own and save it in your Library.", "target": "optimizer", "template": "I am the {{role}} at {{business}}. Task: {{task}}. Audience: {{audience}}. Constraints: up to {{number}} words, {{tone}} tone, no jargon. Deliver as plain text.", "labels": {"number": ["Word limit", "e.g. 120"]}}, "checklist": ["I started from a tested prompt", "The variables have clear names", "The structure and limits stayed fixed", "I saved it with a title that says what it''s for", "I tested the template on 2 different cases"], "tips": [{"title": "Few fields", "text": "Between 3 and 6 variables is ideal. More than that and the template gets tedious to fill in."}, {"title": "Lowercase names, no spaces", "text": "Use names like {{client_type}}. They''re easier to read and always work."}]}'::jsonb from public.learn_lessons where slug = 'criar-template'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
insert into public.learn_lessons (slug, track, sector, sort_order, is_free, duration_min, level, title_pt, title_en, summary_pt, summary_en, is_active)
values ('prompts-imagens', 'avancado', null, 203, false, 6, 'avancado', 'Prompts para imagens', 'Prompts for images', 'A estrutura de 6 elementos para gerar imagens de produto, posts e anúncios com qualquer gerador de imagens.', 'The 6-element structure for generating product shots, posts and ads with any image generator.', true)
on conflict (slug) do update set track=excluded.track, sector=excluded.sector, sort_order=excluded.sort_order, is_free=excluded.is_free, duration_min=excluded.duration_min, level=excluded.level, title_pt=excluded.title_pt, title_en=excluded.title_en, summary_pt=excluded.summary_pt, summary_en=excluded.summary_en, is_active=true, updated_at=now();
insert into public.learn_lesson_content (lesson_id, body_pt, body_en)
select id, '{"problem": "Pedes \"uma imagem bonita do meu produto\" e recebes algo genérico, com mãos estranhas, texto ilegível ou um estilo que não tem nada a ver com a tua marca. Os geradores de imagens precisam de instruções visuais, não de adjetivos.", "steps": [{"title": "Descreve sujeito e cenário", "text": "O quê, onde e quando: \"uma garrafa de azeite de vidro escuro numa mesa de madeira, cozinha rústica, luz da manhã\"."}, {"title": "Define estilo, enquadramento e luz", "text": "Fotografia de produto, plano aproximado, ângulo de 45 graus, luz natural lateral, fundo desfocado. Estes termos controlam o resultado muito mais do que \"bonito\"."}, {"title": "Formato e o que evitar", "text": "Indica a proporção (1:1 para feed, 9:16 para stories) e o que excluir: \"sem texto na imagem, sem pessoas, sem logótipos\". Acrescenta o texto depois, numa ferramenta de design."}], "before": {"prompt": "Faz uma imagem bonita do meu azeite.", "note": "Sem cenário, estilo nem formato: o resultado é aleatório."}, "after": {"prompt": "Fotografia de produto: garrafa de azeite em vidro verde-escuro, sem rótulo, numa mesa de madeira de oliveira, ao lado de um ramo de oliveira e de pão caseiro. Cozinha rústica alentejana ao fundo, desfocada. Luz natural da manhã, lateral e suave. Plano aproximado, ângulo de 45 graus. Cores quentes e naturais. Proporção 4:5. Sem texto, sem pessoas, sem logótipos.", "note": "Sujeito, cenário, estilo, enquadramento, luz e formato. Resultado previsível e coerente com a marca."}, "try": {"intro": "Preenche e abre no Criar Prompt, escolhendo o tipo de saída Imagem.", "target": "builder", "template": "Fotografia de produto: {{produto}}. Cenário: {{contexto}}. Luz: {{luz}}. Plano aproximado, ângulo de 45 graus, fundo desfocado. Proporção {{proporcao}}. Sem texto, sem pessoas, sem logótipos.", "labels": {"produto": ["Produto", "Ex.: garrafa de azeite em vidro verde-escuro"], "contexto": ["Cenário", "Ex.: mesa de madeira, cozinha rústica"], "luz": ["Luz", "Ex.: luz natural da manhã, lateral"], "proporcao": ["Proporção", "Ex.: 4:5"]}}, "checklist": ["Descrevi sujeito e cenário", "Indiquei estilo, enquadramento e luz", "Defini a proporção para o canal", "Disse o que evitar", "Vou acrescentar o texto numa ferramenta de design"], "tips": [{"title": "Rótulos e marcas reais", "text": "Os geradores ainda erram texto e logótipos. Gera a cena sem rótulo e aplica a tua marca depois."}, {"title": "Uma série coerente", "text": "Mantém o mesmo estilo, luz e paleta em todos os prompts de uma campanha. Muda só o produto e o cenário."}]}'::jsonb, '{"problem": "You ask for \"a nice picture of my product\" and get something generic, with strange hands, unreadable text or a style that has nothing to do with your brand. Image generators need visual instructions, not adjectives.", "steps": [{"title": "Describe subject and setting", "text": "What, where and when: \"a dark glass bottle of olive oil on a wooden table, rustic kitchen, morning light\"."}, {"title": "Set style, framing and light", "text": "Product photography, close-up, 45-degree angle, soft natural side light, blurred background. These terms control the result far more than \"nice\"."}, {"title": "Format and what to avoid", "text": "State the aspect ratio (1:1 for feed, 9:16 for stories) and what to exclude: \"no text in the image, no people, no logos\". Add text later in a design tool."}], "before": {"prompt": "Make a nice picture of my olive oil.", "note": "No setting, style or format: the result is random."}, "after": {"prompt": "Product photography: dark green glass bottle of olive oil, no label, on an olive-wood table next to an olive branch and homemade bread. Rustic farmhouse kitchen in the background, blurred. Soft natural morning side light. Close-up, 45-degree angle. Warm, natural colours. Aspect ratio 4:5. No text, no people, no logos.", "note": "Subject, setting, style, framing, light and format. A predictable result that fits the brand."}, "try": {"intro": "Fill in the fields and open in Create Prompt, choosing Image as the output type.", "target": "builder", "template": "Product photography: {{product}}. Setting: {{context}}. Light: {{light}}. Close-up, 45-degree angle, blurred background. Aspect ratio {{aspect_ratio}}. No text, no people, no logos.", "labels": {"product": ["Product", "e.g. dark green glass olive oil bottle"], "context": ["Setting", "e.g. wooden table, rustic kitchen"], "light": ["Light", "e.g. soft morning side light"], "aspect_ratio": ["Aspect ratio", "e.g. 4:5"]}}, "checklist": ["I described subject and setting", "I set style, framing and light", "I chose the aspect ratio for the channel", "I said what to avoid", "I''ll add the text in a design tool"], "tips": [{"title": "Real labels and logos", "text": "Generators still get text and logos wrong. Generate the scene without a label and apply your branding afterwards."}, {"title": "A consistent series", "text": "Keep the same style, light and palette across a campaign''s prompts. Change only the product and the setting."}]}'::jsonb from public.learn_lessons where slug = 'prompts-imagens'
on conflict (lesson_id) do update set body_pt=excluded.body_pt, body_en=excluded.body_en, updated_at=now();
